INSERT INTO Sikshapatri (shloka_number, gujarati_text) VALUES
(11, 'હવે તે વર્ત્યાની રીત કહીએ છીએ જે અમારા જે સત્સંગી તેમણે કોઈ જીવપ્રાણીમાત્રની પણ હિંસા ન કરવી અને જાણીને તો ઝીણા એવા જૂ, માંકડ, ચાંચડ આદિક જીવ તેમની પણ હિંસા કયારેય ન કરવી.'),
(12, 'અને દેવતા અને પિતૃ તેના યજ્ઞને અર્થે પણ બકરાં, મૃગલાં, સસલાં, માછલાં આદિક કોઈ જીવની હિંસા ન કરવી કેમ જે અહિંસા છે તે જ મોટો ધર્મ છે એમ સર્વ શાસ્ત્રમાં કહ્યું છે.'),
(13, 'અને સ્ત્રી, ધન અને રાજ્ય તેની પ્રાપ્તિને અર્થે પણ કોઈ મનુષ્યની હિંસા તો કોઈ પ્રકારે કયારેય પણ ન જ કરવી.'),
(14, 'અને આત્મઘાત તો તીર્થને વિષે પણ ન કરવો ને ક્રોધે કરીને ન કરવો અને કયારેક કોઈ અયોગ્ય આચરણ થઈ જાય તે થકી મૂંઝાઈને પણ આત્મઘાત ન કરવો અને ઝેર ખાઈને તથા ગળે ટૂંપો ખાઈને તથા કૂવે પડીને તથા પર્વત ઉપરથી પડીને ઈત્યાદિક કોઈ રીતે આત્મઘાત ન કરવો.'),
(15, 'અને જે માંસ છે તે તો યજ્ઞનું શેષ હોય તો પણ આપત્કાળમાં પણ કયારેય ન ખાવું અને ત્રણ પ્રકારની સુરા અને અગિયાર પ્રકારનું મદ્ય તે દેવતાનું નૈવેદ્ય હોય તો પણ ન પીવું.'),
(16, 'અને કયારેક પોતાવતે કાંઈક અયોગ્ય આચરણ થઈ ગયું હોય અથવા કોઈ બીજા વતે અયોગ્ય આચરણ થઈ ગયું હોય તો શસ્ત્રાદિકે કરીને પોતાના અંગનું તથા બીજાના અંગનું છેદન ન કરવું અથવા ક્રોધે કરીને પણ પોતાના અંગનું તથા બીજાના અંગનું છેદન ન કરવું.'),
(17, 'અને ધર્મ કરવાને અર્થે પણ અમારા સત્સંગી, કોઈએ ચોરનું કર્મ ન કરવું અને ધણિયાતું જે કાષ્ઠ, પુષ્પ આદિક વસ્તુ, તે તેના ધણીની આજ્ઞા વિના ન લેવું.'),
(18, 'અને અમારા આશ્રિત જે પુરુષ તથા સ્ત્રીઓ તેમણે વ્યભિચાર ન કરવો અને જુગટું આદિક જે વ્યસન તેનો ત્યાગ કરવો અને ભાંગ, મફર, માજમ, ગાંજો એ આદિક જે કેફ કરનાર વસ્તુ, તે ખાવી નહિ અને પીવી પણ નહિ.'),
(19, 'અને જેના હાથનું રાંધેલ અન્ન તથા જેના પાત્રનું જળ તે ખપતું ન હોય તેણે રાંધેલ અન્ન તથા તેના પાત્રનું જળ તે શ્રીકૃષ્ણ ભગવાનની પ્રસાદી-ચરણામૃતના માહાત્મ્યે કરીને પણ જગન્નાથપુરી વિના અન્ય સ્થાનકને વિષે ગ્રહણ ન કરવું અને જગન્નાથપુરીને વિષે જગન્નાથજીનો પ્રસાદ લેવાય તેનો દોષ નહિ.'),
(20, 'અને પોતાના સ્વાર્થની સિદ્ધિને અર્થે પણ કોઈને વિષે મિથ્યા અપવાદ આરોપણ ન કરવો અને કોઈને ગાળ તો કયારેય ન દેવી.'),
(21, 'અને દેવતા, તીર્થ, બ્રાહ્મણ, પતિવ્રતા, સાધુ અને વેદ એમની નિંદા કયારેય ન કરવી અને ન સાંભળવી.'),
(22, 'અને જે દેવતાને સુરા અને માંસનું નૈવેદ્ય થતું હોય અને વળી જે દેવતાને આગળ બકરાં આદિક જીવની હિંસા થતી હોય તે દેવતાનું નૈવેદ્ય ન ખાવું.'),
(23, 'અને માર્ગને વિષે ચાલતે શિવાલયાદિક જે દેવમંદિર આવે તેને જોઈને તેને નમસ્કાર કરવા અને આદરથકી તે દેવનું દર્શન કરવું.'),
(24, 'અને પોતપોતાના વર્ણાશ્રમનો જે ધર્મ તે કોઈ સત્સંગીએ ત્યાગ ન કરવો અને પરધર્મનું આચરણ ન કરવું તથા પાખંડ ધર્મનું આચરણ ન કરવું તથા કલ્પિત ધર્મનું આચરણ ન કરવું.'),
(25, 'અને જેના વચનને સાંભળવે કરીને શ્રીકૃષ્ણ ભગવાનની ભક્તિ ને પોતાનો ધર્મ એ બે થકી પડી જવાય તેના મુખ થકી ભગવાનની કથાવાર્તા ન સાંભળવી.'),
(26, 'અને જે સત્ય વચન બોલવે કરીને પોતાનો દ્રોહ થાય તથા પારકો દ્રોહ થાય એવું જે સત્ય વચન, તે કયારેય ન બોલવું અને જે કૃતઘ્ની હોય તેના સંગનો ત્યાગ કરવો અને વ્યવહારકાર્યને વિષે કોઈની લાંચ ન લેવી.'),
(27, 'અને ચોર, પાપી, વ્યસની, પાખંડી, કામી તથા કીમિયા આદિક ક્રિયાએ કરીને જનનો ઠગનારો, એ છ પ્રકારના જે મનુષ્ય તેમનો સંગ ન કરવો.'),
(28, 'અને જે મનુષ્ય, ભક્તિનું અથવા જ્ઞાનનું આલંબન કરીને સ્ત્રી, દ્રવ્ય અને રસાસ્વાદ તેને વિષે અતિશય લોલુપ થકા પાપને વિષે પ્રવર્તતા હોય, તે મનુષ્યનો સમાગમ ન કરવો.'),
(29, 'અને જે શાસ્ત્રને વિષે શ્રીકૃષ્ણ ભગવાન તથા શ્રીકૃષ્ણ ભગવાનના જે વારાહાદિક અવતાર તેમનું યુક્તિએ કરીને ખંડન કર્યું હોય એવાં જે શાસ્ત્ર તે કયારેય ન માનવાં અને ન સાંભળવાં.'),
(30, 'અને ગાળ્યા વિનાનું જે જળ તથા દૂધ તે ન પીવું અને જે જળને વિષે ઝીણાં જીવ ઘણાંક હોય તે જળે કરીને સ્નાનાદિક ક્રિયા ન કરવી.'),
(31, 'અને જે ઔષધ દારૂ તથા માંસ તેણે યુક્ત હોય તે ઔષધ કયારેય ન ખાવું અને વળી જે વૈદ્યના આચરણને જાણતા ન હોઈએ તે વૈદ્યે આપ્યું જે ઔષધ તે પણ કયારેય ન ખાવું.'),
(32, 'લોક અને શાસ્ત્ર તેમણે મળમૂત્ર કરવાને અર્થે વર્જ્યાં એવાં સ્થાનક જે જીર્ણ દેવાલય તથા નદી તળાવના આરા તથા માર્ગ તથા વાવેલું ખેતર તથા વૃક્ષની છાયા તથા ફૂલવાડી-બગીચા એ આદિક જે સ્થાનક તેમને વિષે કયારેય પણ મળમૂત્ર ન કરવું તથા થૂંકવું પણ નહિ.'),
(33, 'અને ચોરમાર્ગે કરીને પેસવું નહિ અને નીસરવું નહિ અને જે સ્થાનક ધણિયાતું હોય તે સ્થાનકને વિષે તેના ધણીને પૂછયા વિના ઉતારો ન કરવો.'),
(34, 'અને અમારા સત્સંગી જે પુરુષમાત્ર તેમણે બાઈ માણસના મુખથકી જ્ઞાનવાર્તા ન સાંભળવી અને સ્ત્રીઓ સાથે વિવાદ ન કરવો તથા રાજા સંગાથે તથા રાજાના માણસ સંગાથે વિવાદ ન કરવો.'),
(35, 'અને ગુરુનું અપમાન ન કરવું તથા જે અતિશય શ્રેષ્ઠ મનુષ્ય હોય તથા જે લોકને વિષે પ્રતિષ્ઠિત મનુષ્ય હોય તથા જે વિદ્વાન મનુષ્ય હોય તથા જે શસ્ત્રધારી મનુષ્ય હોય તે સર્વેનું અપમાન ન કરવું.'),
(36, 'અને વિચાર્યા વિના તત્કાળ કાંઈ કાર્ય ન કરવું અને ધર્મ સંબંધી જે કાર્ય તે તો તત્કાળ કરવું અને પોતે જે વિદ્યા ભણ્યા હોઈએ તે બીજાને ભણાવવી અને નિત્ય પ્રત્યે સાધુનો સમાગમ કરવો.'),
(37, 'અને ગુરુ, દેવ અને રાજા એ ત્રણના દર્શનને અર્થે જ્યારે જવું ત્યારે ઠાલે હાથે ન જવું અને કોઈનો વિશ્વાસઘાત ન કરવો અને પોતાને મુખે કરીને પોતાનાં વખાણ ન કરવાં.'),
(38, 'અને જે વસ્ત્ર પહેર્યે થકે પણ પોતાનાં અંગ દેખાય તેવું જે ભૂંડું વસ્ત્ર તે અમારા સત્સંગી તેમણે ન પહેરવું.'),
(39, 'અને શ્રીકૃષ્ણ ભગવાનની જે ભક્તિ તે ધર્મે રહિત એવી કોઈ પ્રકારે ન કરવી અને અજ્ઞાની એવા જે મનુષ્ય તેમની નિંદાના ભય થકી શ્રીકૃષ્ણ ભગવાનની સેવાનો ત્યાગ કરવો જ નહિ.'),
(40, 'અને ઉત્સવના દિવસને વિષે તથા નિત્ય પ્રત્યે શ્રીકૃષ્ણના મંદિરમાં આવ્યા એવા જે સત્સંગી પુરુષ તેમણે તે મંદિરને વિષે સ્ત્રીઓનો સ્પર્શ ન કરવો તથા સ્ત્રીઓ તેમણે પુરુષનો સ્પર્શ ન કરવો અને મંદિરમાંથી નીસર્યા પછી પોતપોતાની રીતે વર્તવું.'),
(41, 'અને ધર્મવંશી ગુરુથકી શ્રીકૃષ્ણની દીક્ષાને પામ્યા એવા જે બ્રાહ્મણ, ક્ષત્રિય અને વૈશ્ય એ ત્રણ વર્ણના અમારા સત્સંગી તેમણે કંઠને વિષે તુલસીની બેવડી માળા નિત્યે ધારવી અને લલાટ, હૃદય અને બે હાથ એ ચારે ઠેકાણે ઊર્ધ્વપુંડ્ર તિલક કરવું.'),
(42, 'અને તે તિલક જે તે ગોપીચંદને કરીને કરવું અથવા ભગવાનની પૂજા કરતાં બાકી રહ્યું અને કેસર કુંકુમાદિકે યુક્ત એવા જે પ્રસાદી ચંદન તેણે કરીને તિલક કરવું.'),
(43, 'અને તે તિલકના મધ્યને વિષે જ ગોળ એવો જે ચાંદલો તે જે તે ગોપીચંદને કરીને કરવો અથવા રાધિકાજી અને લક્ષ્મીજી તેનું પ્રસાદી એવું જે કુંકુમ તેણે કરીને તે ચાંદલો કરવો.'),
(44, 'અને પોતાના ધર્મને વિષે રહ્યા અને શ્રીકૃષ્ણના ભક્ત એવા જે સત્શૂદ્ર તેમણે તો તુલસીની માળા અને ઊર્ધ્વપુંડ્ર તિલક તે બ્રાહ્મણ, ક્ષત્રિય, વૈશ્યની પેઠે ધારવાં.'),
(45, 'અને તે સત્શૂદ્ર થકી બીજા જે જાતિએ કરીને ઉતરતા એવા ભક્તજન તેમણે તો ચંદનાદિક કાષ્ઠની જે બેવડી માળા તે ભગવાનની પ્રસાદી કરાવીને કંઠને વિષે ધારવી અને લલાટને વિષે કેવળ ચાંદલો કરવો પણ તિલક ન કરવું.'),
(46, 'અને જે બ્રાહ્મણાદિકને ત્રિપુંડ્ર જે આડું તિલક કરવું તથા રુદ્રાક્ષની માળા ધારવી એ બે વાનાં પોતાની કુળ પરંપરાએ કરીને ચાલ્યાં આવ્યાં હોય અને તે બ્રાહ્મણાદિક અમારા આશ્રિત થયા હોય તો પણ તેમણે તે ત્રિપુંડ્ર અને રુદ્રાક્ષનો કયારેય ત્યાગ ન કરવો.'),
(47, 'અને નારાયણ અને શિવજી, એ બેનું એકાત્મપણું જ જાણવું કેમ જે વેદને વિષે એ બેનું બ્રહ્મરૂપે કરીને પ્રતિપાદન કર્યું છે.'),
(48, 'અને અમારા આશ્રિત જે મનુષ્ય તેમણે શાસ્ત્રે કહ્યો જે આપદ્ધર્મ તે અલ્પ આપત્કાળને વિષે મુખ્યપણે કરીને કયારેય ગ્રહણ ન કરવો.'),
(49, 'અને અમારા સત્સંગી, તેમણે નિત્ય સૂર્ય ઊગ્યાથી પ્રથમ જ જાગવું અને શ્રીકૃષ્ણ ભગવાનનું સ્મરણ કરીને પછી શૌચવિધિ કરવા જવું.'),
(50, 'અને પછી એક સ્થાનને વિષે બેસીને દાતણ કરવું અને પછી પવિત્ર જળે કરીને સ્નાન કરીને પછી ધોયેલું વસ્ત્ર એક પહેરવું અને એક ઓઢવું.'),
(51, 'અને ત્યાર પછી પવિત્ર પૃથ્વીને વિષે પાથર્યું અને શુદ્ધ ને કોઈ બીજા આસનને અડ્યું ન હોય અને જે ઉપર સારી પેઠે બેસાય એવું જે આસન તેને વિષે પૂર્વમુખે અથવા ઉત્તરમુખે બેસીને આચમન કરવું.'),
(52, 'અને પછી સત્સંગી પુરુષમાત્રને ચાંદલે સહિત ઊર્ધ્વપુંડ્ર તિલક કરવું અને સુવાસિની જે સ્ત્રીઓ તેમણે તો પોતાના ભાલને વિષે કુંકુમનો ચાંદલો કરવો.'),
(53, 'અને તે વિધવા સ્ત્રીઓ માત્રને પોતાના ભાલને વિષે તિલક ન કરવું ને ચાંદલો પણ ન કરવો અને તે પછી તે સર્વે જે અમારા સત્સંગી તેમણે મને કરીને કલ્પ્યાં જે ચંદન અને પુષ્પાદિક ઉપચાર તેણે કરીને શ્રીકૃષ્ણ ભગવાનની માનસી પૂજા કરવી.'),
(54, 'અને તે પછી શ્રીરાધાકૃષ્ણની જે ચિત્ર પ્રતિમા તેનું આદરથકી દર્શન કરીને નમસ્કાર કરીને પછી પોતાના સામર્થ્ય પ્રમાણે શ્રીકૃષ્ણનો જે અષ્ટાક્ષર મંત્ર તેનો જપ કરીને તે પછી પોતાનું વ્યાવહારિક કામકાજ કરવું.'),
(55, 'અને જે અમારા સત્સંગીમાં અંબરીષ રાજાની પેઠે આત્મનિવેદી એવા ઉત્તમ ભક્ત હોય તેમણે પણ પ્રથમ કહ્યું તેવી રીતે અનુક્રમે કરીને માનસી પૂજા પર્યન્ત સર્વે ક્રિયા કરવી.'),
(56, 'અને તેજે આત્મનિવેદી ભક્ત તેમણે પાષાણની અથવા ધાતુની જે શ્રીકૃષ્ણ ભગવાનની પ્રતિમા અથવા શાલિગ્રામ તેની જે પૂજા, તે દેશકાળને અનુસરીને પોતાના સામર્થ્ય પ્રમાણે પ્રાપ્ત થયાં જે ચંદન, પુષ્પ, ફળાદિક વસ્તુ તેણે કરીને કરવી અને પછી શ્રીકૃષ્ણ ભગવાનનો જે અષ્ટાક્ષર મંત્ર તેનો જપ કરવો.'),
(57, 'અને તે પછી શ્રીકૃષ્ણ ભગવાનનાં જે સ્તોત્ર અથવા ગ્રંથ તેનો જે પાઠ તે પોતાના સામર્થ્ય પ્રમાણે કરવો અને જે સંસ્કૃત ન ભણ્યા હોય તેમણે શ્રીકૃષ્ણ ભગવાનનું નામ કીર્તન કરવું.'),
(58, 'અને પછી શ્રીકૃષ્ણભગવાનને નૈવેદ્ય કરીને પછી તે પ્રસાદી એવું જે અન્ન તે જમવું અને તે જે આત્મનિવેદી વૈષ્ણવ, તેમણે સર્વકાળને વિષે પ્રીતિએ કરીને શ્રીકૃષ્ણ ભગવાનની સેવાપરાયણ થવું.'),
(59, 'અને નિર્ગુણ કહેતાં માયાના જે સત્ત્વાદિક ત્રણ ગુણ તેણે રહિત એવા જે શ્રીકૃષ્ણ ભગવાન તેના સંબંધ થકી તે આત્મનિવેદી ભક્તની જે સર્વે ક્રિયા તે નિર્ગુણ થાય છે. તે હેતુ માટે તે આત્મનિવેદી ભક્ત જે તે નિર્ગુણ કહ્યા છે.'),
(60, 'અને એ જે આત્મનિવેદી ભક્ત તેમણે શ્રીકૃષ્ણ ભગવાનને અર્પણ કર્યા વિનાનું જળ પણ કયારેય ન પીવું અને પત્ર, કંદ, ફળાદિક જે વસ્તુ તે, પણ શ્રીકૃષ્ણ ભગવાનને અર્પણ કર્યા વિનાનું ન ખાવું.'),
(61, 'અને વળી સર્વે જે અમારા સત્સંગી, તેમણે વૃદ્ધપણાથકી અથવા કોઈ મોટા આપત્કાળે કરીને અસમર્થપણું થઈ ગયે સતે પોતે સેવવાનું જે શ્રીકૃષ્ણનું સ્વરૂપ તે બીજા ભક્તને આપીને પોતે પોતાના સામર્થ્ય પ્રમાણે વર્તવું.'),
(62, 'અને જે શ્રીકૃષ્ણનું સ્વરૂપ, પોતાને સેવવાને અર્થે ધર્મવંશના જે આચાર્ય, તેમણે જ આપ્યું હોય અથવા તે આચાર્યે જે સ્વરૂપની પ્રતિષ્ઠા કરી હોય તે જ સ્વરૂપને સેવવું અને તે વિના બીજું જે શ્રીકૃષ્ણનું સ્વરૂપ તે તો નમસ્કાર કરવા યોગ્ય છે; પણ સેવવા યોગ્ય નથી.'),
(63, 'અને અમારા જે સર્વે સત્સંગી તેમણે નિત્ય પ્રત્યે સાયંકાળે ભગવાનના મંદિર પ્રત્યે જવું અને તે મંદિરને વિષે શ્રીરાધિકાજીના પતિ એવા જે શ્રીકૃષ્ણ ભગવાન તેના નામનું ઉચ્ચ સ્વરે કરીને કીર્તન કરવું.'),
(64, 'અને તે શ્રીકૃષ્ણની જે કથાવાર્તા તે પરમ આદર થકી કરવી ને સાંભળવી અને ઉત્સવને દિવસે વાજિંત્રે સહિત શ્રીકૃષ્ણનાં કીર્તન કરવાં.'),
(65, 'અને અમારા આશ્રિત જે સર્વે સત્સંગી, તેમણે જે પ્રકારે પૂર્વે કહ્યું એ પ્રકારે કરીને જ નિત્ય પ્રત્યે કરવું અને સંસ્કૃત અને પ્રાકૃત એવા જે સદ્‌ગ્રંથ તેમનો અભ્યાસ પણ પોતાની બુદ્ધિને અનુસારે કરવો.'),
(66, 'અને જે મનુષ્ય જેવા ગુણે કરીને યુક્ત હોય તે મનુષ્યને તેવા કાર્યને વિષે વિચારીને જ પ્રેરવો પણ જે કાર્યને વિષે જે યોગ્ય ન હોય તે કાર્યને વિષે તેને કયારેય ન પ્રેરવો.'),
(67, 'અને પોતાના જે સેવક હોય તે સર્વની પોતાના સામર્થ્ય પ્રમાણે અન્નવસ્ત્રાદિકે કરીને યથાયોગ્ય સંભાવના નિરંતર રાખવી.'),
(68, 'અને જે પુરુષ જેવા ગુણવાળો હોય તે પુરુષને તેવા વચને કરીને દેશકાળાનુસારે યથાયોગ્ય બોલાવવો પણ એથી બીજી રીતે ન બોલાવવો.'),
(69, 'અને વિનયે કરીને યુક્ત એવા જે અમારા આશ્રિત સત્સંગી તેમણે ગુરુ, રાજા, અતિ વૃદ્ધ, ત્યાગી, વિદ્વાન્‌ અને તપસ્વી એ છ જણા આવે ત્યારે સન્મુખ ઊઠવું તથા આસન આપવું તથા મધુર વચને બોલાવવું ઈત્યાદિક ક્રિયાએ કરીને એમનું સન્માન કરવું.'),
(70, 'અને ગુરુ, દેવ ને રાજા એમને સમીપે તથા સભાને વિષે પગ ઉપર પગ ચઢાવીને ન બેસવું તથા વસ્ત્રે કરીને ઢીંચણને બાંધીને ન બેસવું.'),
(71, 'અને અમારા આશ્રિત જે સર્વે સત્સંગી તેમણે પોતાના આચાર્ય સંગાથે કયારેય પણ વિવાદ ન કરવો અને પોતાના સામર્થ્ય પ્રમાણે અન્ન, ધન, વસ્ત્રાદિકે કરીને તે પોતાના આચાર્યને પૂજવા.'),
(72, 'અમારા જે આશ્રિતજન, તેમણે પોતાના આચાર્યને આવતા સાંભળીને આદર થકી તત્કાળ સન્મુખ જવું અને તે આચાર્ય પોતાના ગામથી પાછા પધારે ત્યારે ગામની ભાગોળ સુધી વળાવવા જવું.'),
(73, 'અને ઘણુંક છે ફળ જેને વિષે એવું પણ જે કર્મ, તે જો ધર્મે રહિત હોય તો તેનું આચરણ ન જ કરવું; કેમ જે ધર્મ છે તે જ સર્વ પુરુષાર્થનો આપનારો છે માટે કોઈક ફળના લોભે કરીને ધર્મનો ત્યાગ ન કરવો.'),
(74, 'અને પૂર્વે થયા જે મોટા પુરુષ તેમણે પણ જો કયારેય અધર્માચરણ કર્યું હોય તો તેનું ગ્રહણ ન કરવું અને તેમણે જે ધર્માચરણ કર્યું હોય તેનું ગ્રહણ કરવું.'),
(75, 'અને કોઈની પણ જે ગુહ્યવાર્તા તે તો કોઈ ઠેકાણે પણ પ્રકાશ કરવી જ નહિ ને જે જીવનું જેવી રીતે સન્માન કરવું ઘટતું હોય તેનું તેવી રીતે જ સન્માન કરવું પણ સમદૃષ્ટિએ કરીને એ મર્યાદાનું ઉલ્લંઘન કરવું નહિ.'),
(76, 'અને અમારા જે સર્વે સત્સંગી તેમણે ચાતુર્માસને વિષે વિશેષ નિયમ ધારવો અને જે મનુષ્ય અસમર્થ હોય તેમણે તો એક શ્રાવણ માસને વિષે વિશેષ નિયમ ધારવો.'),
(77, 'અને તે વિશેષ નિયમ તે કયા, તો ભગવાનની કથાનું શ્રવણ કરવું તથા કથા વાંચવી तथा ભગવાનના ગુણનું કીર્તન કરવું તથા પંચામૃત સ્નાને કરીને ભગવાનની મહાપૂજા કરવી તથા ભગવાનના મંત્રનો જપ કરવો તથા સ્તોત્રનો પાઠ કરવો તથા ભગવાનને પ્રદક્ષિણાઓ કરવી.'),
(78, 'તથા ભગવાનને સાષ્ટાંગ નમસ્કાર કરવા. એ જે આઠ પ્રકારના નિયમ તે અમે ઉત્તમ માન્યા છે. તે માટે એ નિયમમાંથી કોઈ એક નિયમ જે તે ચોમાસાને વિષે વિશેષપણે ભક્તિએ કરીને ધારવો.'),
(79, 'અને સર્વ જે એકાદશીઓ તેમનું વ્રત જે તે આદર થકી કરવું તથા શ્રીકૃષ્ણ ભગવાનના જે જન્માષ્ટમી આદિક જન્મદિવસ તેમનું વ્રત આદર થકી કરવું તથા શિવરાત્રિનું વ્રત જે તે આદર થકી કરવું અને તે વ્રતના દિવસને વિષે મોટા ઉત્સવ કરવા.'),
(80, 'અને જે દિવસે વ્રતનો ઉપવાસ કર્યો હોય તે દિવસે અતિશય યત્ને કરીને દિવસની નિદ્રાનો ત્યાગ કરવો કેમ જે જેમ મૈથુને કરીને મનુષ્યના ઉપવાસનો નાશ થાય છે તેમ જ દિવસની નિદ્રાએ કરીને મનુષ્યના ઉપવાસનો નાશ થઈ જાય છે.'),
(81, 'અને સર્વ વૈષ્ણવના રાજા એવા જે શ્રી વલ્લભાચાર્ય તેના પુત્ર જે શ્રી વિઠ્ઠલનાથજી તે જે તે જે વ્રત અને ઉત્સવના નિર્ણયને કરતા હવા.'),
(82, 'અને તે વિઠ્ઠલનાથજીએ કર્યો જે નિર્ણય, તેને જ અનુસરીને સર્વે વ્રત ને ઉત્સવ કરવા અને તે વિઠ્ઠલનાથજીએ કહી જે શ્રીકૃષ્ણની સેવારીતિ તેનું જ ગ્રહણ કરવું.'),
(83, 'અને સર્વે જે અમારા આશ્રિત તેમણે દ્વારિકા આદિક જે તીર્થ તેમની યાત્રા જે તે પોતાના સામર્થ્ય પ્રમાણે યથાવિધિએ કરીને કરવી અને વળી પોતાના સામર્થ્ય પ્રમાણે દીનજનને વિષે દયાવાન થવું.'),
(84, 'અને અમારા જે આશ્રિત, તેમણે વિષ્ણુ, શિવ, ગણપતિ, પાર્વતી અને સૂર્ય એ પાંચ દેવ જે તે પૂજ્યપણે કરીને માનવા.'),
(85, 'અને જો કયારેક ભૂતપ્રેતાદિકનો ઉપદ્રવ થાય ત્યારે તો નારાયણ કવચનો જપ કરવો અથવા હનુમાનના મંત્રનો જપ કરવો પણ એ વિના બીજા કોઈ ક્ષુદ્ર દેવના સ્તોત્ર અને મંત્રનો જપ ન કરવો.'),
(86, 'અને સૂર્યનું ને ચંદ્રમાનું ગ્રહણ થયે સતે અમારા જે સર્વે સત્સંગી તેમણે બીજી સર્વે ક્રિયાનો તત્કાળ ત્યાગ કરીને પવિત્ર થઈને શ્રીકૃષ્ણ ભગવાનના મંત્રનો જપ કરવો.'),
(87, 'અને તે ગ્રહણ મુકાઈ રહ્યા પછી વસ્ત્રે સહિત સ્નાન કરીને જે અમારા ગૃહસ્થ સત્સંગી હોય તેમણે પોતાના સામર્થ્ય પ્રમાણે દાન કરવું અને જે ત્યાગી હોય તેમણે ભગવાનની પૂજા કરવી.'),
(88, 'અને અમારા સત્સંગી એવા જે ચારે વર્ણના મનુષ્ય તેમણે જન્મનું સૂતક તથા મરણનું સૂતક તે પોતપોતાના સંબંધને અનુસારે કરીને યથાશાસ્ત્ર પાળવું.'),
(89, 'અને જે બ્રાહ્મણ વર્ણ હોય તેમણે શમ, દમ, ક્ષમા અને સંતોષ એ આદિક જે ગુણ તેમણે યુક્ત થવું અને જે ક્ષત્રિય વર્ણ હોય તેમણે શૂરવીરપણું અને ધીરજ એ આદિક જે ગુણ તેમણે યુક્ત થવું.'),
(90, 'અને વૈશ્ય વર્ણ હોય તેમણે કૃષિકર્મ તથા વણજ વ્યાપાર તથા વ્યાજવટો એ આદિક જે વૃત્તિઓ તેમણે કરીને વર્તવું અને જે શૂદ્ર વર્ણ હોય તેમણે બ્રાહ્મણાદિક ત્રણ વર્ણની સેવા કરવી એ આદિક જે વૃત્તિઓ તેમણે કરીને વર્તવું.'),
(91, 'અને જે દ્વિજ હોય તેમણે ગર્ભાધાનાદિક સંસ્કાર તથા આહ્નિક તથા શ્રાદ્ધ એ ત્રણ જે તે પોતાના ગૃહ્યસૂત્રને અનુસારે કરીને જેવો જેનો અવસર હોય અને જેવી ધનસંપત્તિ હોય તે પ્રમાણે કરવાં.'),
(92, 'અને કયારેક જાણે અથવા અજાણે જો નાનું મોટું પાપ થઈ જાય તો પોતાની શક્તિ પ્રમાણે તે પાપનું પ્રાયશ્ચિત કરવું.'),
(93, 'અને ચાર વેદ તથા વ્યાસસૂત્ર તથા શ્રીમદ્‌ ભાગવત નામે પુરાણ તથા મહાભારતને વિષે તો શ્રીવિષ્ણુસહસ્રનામ.'),
(94, 'તથા શ્રીભગવદ્‌ ગીતા તથા વિદુરજીએ કહેલી જે નીતિ તથા સ્કંદપુરાણનો જે વિષ્ણુખંડ તેને વિષે રહ્યું એવું જે શ્રીવાસુદેવમાહાત્મ્ય.'),
(95, 'અને ધર્મશાસ્ત્રના મધ્યમાં રહી એવી જે યાજ્ઞવલ્કય ઋષિની સ્મૃતિ એ જે આઠ સત્શાસ્ત્ર તે અમને ઈષ્ટ છે.'),
(96, 'અને પોતાના હિતને ઈચ્છતા એવા જે અમારા સર્વે શિષ્ય તેમણે એ આઠ સત્શાસ્ત્ર જે તે સાંભળવાં અને અમારા આશ્રિત જે દ્વિજ તેમણે એ સત્શાસ્ત્ર જે તે ભણવાં તથા ભણાવવાં તથા એમની કથા કરવી.'),
(97, 'અને તે આઠ સચ્છાસ્ત્રમાંથી આચાર, વ્યવહાર અને પ્રાયશ્ચિત એ ત્રણનો જે નિર્ણય કરવો તેને વિષે તો મિતાક્ષરા ટીકાએ યુક્ત એવી જે યાજ્ઞવલ્કય ઋષિની સ્મૃતિનું તેનું ગ્રહણ કરવું.'),
(98, 'અને વળી એ આઠ સચ્છાસ્ત્રને વિષે જે શ્રીમદ્‌ ભાગવત પુરાણ તેના દશમ ને પંચમ નામે જે બે સ્કંધ તે જેતે શ્રીકૃષ્ણ ભગવાનનું માહાત્મ્ય જાણવાને અર્થે સર્વથી અધિકપણે જાણવા.'),
(99, 'અને દશમસ્કંધ તથા પંચમસ્કંધ તથા યાજ્ઞવલ્કયની સ્મૃતિ, એ જે ત્રણ તે અનુક્રમે કરીને અમારું ભક્તિશાસ્ત્ર, યોગશાસ્ત્ર અને ધર્મશાસ્ત્ર છે કહેતાં, દશમસ્કંધ તે ભક્તિશાસ્ત્ર છે અને પંચમસ્કંધ તે યોગશાસ્ત્ર છે અને યાજ્ઞવલ્કયની સ્મૃતિ તે ધર્મશાસ્ત્ર છે એમ જાણવું.'),
(100, 'અને શ્રી રામાનુજાચાર્યે કર્યું એવું જે વ્યાસસૂત્રનું શ્રીભાષ્ય તથા શ્રીભગવદ્્ગીતાનું ભાષ્ય એ જે બે, તે અમારું અધ્યાત્મશાસ્ત્ર છે એમ જાણવું.'),
(101, 'અને એ સર્વે સત્શાસ્ત્રને વિષે જે વચન તે જેતે શ્રીકૃષ્ણ ભગવાનનું સ્વરૂપ તથા ધર્મ તથા ભક્તિ તથા વૈરાગ્ય એ ચારના અતિ ઉત્કર્ષપણાને કહેતાં હોય.'),
(102, 'તે વચન જે તે બીજાં વચન કરતાં પ્રધાનપણે માનવાં અને શ્રીકૃષ્ણ ભગવાનની ભક્તિ, તે જે તે ધર્મે સહિત જ કરવી. એવી રીતે તે સર્વે સત્શાસ્ત્રનું રહસ્ય છે.'),
(103, 'અને શ્રુતિ, સ્મૃતિ તેમણે પ્રતિપાદન કર્યો એવો જે સદાચાર, તે ધર્મ જાણવો અને શ્રીકૃષ્ણ ભગવાનને વિષે માહાત્મ્યજ્ઞાને સહિત જે ઘણો સ્નેહ તે ભક્તિ જાણવી.'),
(104, 'અને શ્રીકૃષ્ણ ભગવાન વિના અન્ય પદાર્થમાં પ્રીતિ નહિ, તે વૈરાગ્ય જાણવો અને જીવ માયા અને ઈશ્વર તેમનાં સ્વરૂપને જે રૂડી રીતે જાણવું, તેને જ્ઞાન કહીએ.'),
(105, 'અને જે જીવ છે, તે હૃદયને વિષે રહ્યો છે ને અણુ સરખો સૂક્ષ્મ છે ને ચૈતન્યરૂપ છે ને જાણનારો છે અને પોતાની જ્ઞાનશક્તિએ કરીને નખથી શિખાપર્યંત સમગ્ર પોતાના દેહ પ્રત્યે વ્યાપીને રહ્યો છે અને અછેદ્ય, અભેદ્ય, અજર, અમર ઈત્યાદિક છે લક્ષણ જેનાં એવો જીવ છે એમ જાણવો.'),
(106, 'અને જે માયા છે તે ત્રિગુણાત્મિકા છે ને અંધકારરૂપ છે ને શ્રીકૃષ્ણ ભગવાનની શક્તિ છે અને આ જીવને દેહ તથા દેહના જે સંબંધી, તેમને વિષે અહં મમત્વની કરાવનારી છે, એમ માયાને જાણવી.'),
(107, 'અને જે ઈશ્વર છે તે જે તે જેમ હૃદયને વિષે જીવ રહ્યો છે તેમ તે જીવને વિષે અંતર્યામીપણે કરીને રહ્યા છે ને સ્વતંત્ર છે ને સર્વ જીવને કર્મફળના આપનારા છે એમ ઈશ્વરને જાણવા.'),
(108, 'અને તે ઈશ્વર તે કયા, તો પરબ્રહ્મ પુરુષોત્તમ એવા જે શ્રીકૃષ્ણ ભગવાન તે ઈશ્વર છે અને તે શ્રીકૃષ્ણ જે તે આપણા ઈષ્ટદેવ છે ને ઉપાસના કરવા યોગ્ય છે અને સર્વ અવતારના કારણ છે.'),
(109, 'અને સમર્થ એવા જે શ્રીકૃષ્ણ તે જે તે રાધિકાજીએ યુક્ત હોય ત્યારે રાધાકૃષ્ણ એવે નામે જાણવા અને રુક્મિણી રૂપ જે લક્ષ્મી તેમણે યુક્ત હોય ત્યારે લક્ષ્મીનારાયણ એવે નામે જાણવા.'),
(110, 'અને એ શ્રીકૃષ્ણ જે તે અજુર્ને યુક્ત હોય ત્યારે નરનારાયણ એવે નામે જાણવા અને વળી તે શ્રીકૃષ્ણ જેતે બળભદ્રાદિકને યોગે કરીને તે તે નામે કહેવાય છે એમ જાણવું.'),
(111, 'અને એ જે રાધાદિક ભક્ત તે જે તે કયારેક તો તે શ્રીકૃષ્ણ ભગવાનને પડખે હોય છે અને કયારેક તો અતિ સ્નેહે કરીને શ્રીકૃષ્ણ ભગવાનના અંગને વિષે રહે છે ત્યારે તો તે શ્રીકૃષ્ણ ભગવાન એકલા જ હોય એમ જાણવા.'),
(112, 'એ હેતુ માટે એ શ્રીકૃષ્ણ ભગવાનનાં જે સ્વરૂપ તેમને વિષે સર્વે પ્રકારે કરીને ભેદ ન જાણવો અને ચતુર્ભુજપણું, અષ્ટભુજપણું, સહસ્રભુજપણું ઈત્યાદિક જે ભેદ જણાય છે તે તો દ્વિભુજ એવા જે તે શ્રીકૃષ્ણ તેમની ઈચ્છાએ કરીને છે એમ જાણવું.'),
(113, 'અને એવા જે તે શ્રીકૃષ્ણ ભગવાન તેની જે ભક્તિ તે જે તે પૃથ્વીને વિષે સર્વ મનુષ્ય તેમણે કરવી અને તે ભક્તિ થકી બીજું કલ્યાણકારી સાધન કાંઈ નથી એમ જાણવું.'),
(114, 'અને વિદ્યાદિક ગુણવાળા જે પુરુષ તેમના ગુણવાન પણાનું એ જ પરમ ફળ જાણવું. કયું તો જે શ્રીકૃષ્ણ ભગવાનને વિષે ભક્તિ કરવી ને સત્સંગ કરવો અને એમ ભક્તિ ને સત્સંગ એ બે વિના તો વિદ્વાન હોય તે પણ અધોગતિને પામે છે.'),
(115, 'અને શ્રીકૃષ્ણ ભગવાન તથા શ્રીકૃષ્ણ ભગવાનના જે અવતાર તે જે તે ધ્યાન કરવા યોગ્ય છે તથા શ્રીકૃષ્ણ ભગવાનની જે પ્રતિમા તે પણ ધ્યાન કરવા યોગ્ય છે; માટે એમનું ધ્યાન કરવું અને મનુષ્ય તથા દેવાદિક જે જીવ તે તો શ્રીકૃષ્ણ ભગવાનના ભક્ત હોય અને બ્રહ્મવેત્તા હોય તો પણ ધ્યાન કરવા યોગ્ય નથી માટે એમનું ધ્યાન ન કરવું.'),
(116, 'અને સ્થૂળ, સૂક્ષ્મ અને કારણ એ જે ત્રણ દેહ તે થકી વિલક્ષણ એવો જે પોતાનો જીવાત્મા તેને બ્રહ્મરૂપની ભાવના કરીને પછી તે બ્રહ્મરૂપે કરીને શ્રીકૃષ્ણ ભગવાનની ભક્તિ જે તે સર્વકાળને વિષે કરવી.'),
(117, 'અને શ્રીમદ્‌ ભાગવત પુરાણનો જે દશમસ્કંધ તે જે તે નિત્યપ્રત્યે આદર થકી સાંભળવો અથવા વર્ષોવર્ષ એકવાર સાંભળવો અને જે પંડિત હોય તેમણે નિત્ય પ્રત્યે વાંચવો અથવા વર્ષોવર્ષ એકવાર વાંચવો.'),
(118, 'અને એ જે દશમસ્કંધ તેનું પુરશ્ચરણ જે તે પુણ્ય સ્થાનકને વિષે પોતાના સામર્થ્ય પ્રમાણે કરવું. કરાવવું અને વળી વિષ્ણુસહસ્રનામ આદિક જે સચ્છાસ્ત્ર તેનું પુરશ્ચરણ પણ પોતાના સામર્થ્ય પ્રમાણે કરવું, કરાવવું. તે પુરશ્ચરણ કેવું છે, તો પોતાના મનવાંછિત ફળને આપે એવું છે.'),
(119, 'અને કષ્ટની દેનારી એવી કોઈ દેવસંબંધી આપદા આવી પડે તથા મનુષ્યસંબંધી આપદા આવી પડે તથા રોગાદિક આપદા આવી પડે તેને વિષે જેમ પોતાની ને બીજાની રક્ષા થાય તેમ વર્તવું પણ બીજી રીતે ન વર્તવું.'),
(120, 'અને આચાર, વ્યવહાર અને પ્રાયશ્ચિત એ જે ત્રણ વાનાં તે જેતે દેશ, કાળ, અવસ્થા, દ્રવ્ય, જાતિ અને સામર્થ્ય એટલાંને અનુસારે કરીને જાણવાં.'),
(121, 'અને અમારો જે મત તે વિશિષ્ટાદ્વૈત છે એમ જાણવું અને અમને પ્રિય એવું જે ધામ તે ગોલોક છે એમ જાણવું અને તે ધામને વિષે બ્રહ્મરૂપે કરીને જે શ્રીકૃષ્ણ ભગવાનની સેવા કરવી તે અમે મુક્તિ માની છે એમ જાણવું.'),
(122, 'અને આ જે પૂર્વે સર્વે ધર્મ કહ્યા તે જે તે અમારા આશ્રિત જે ત્યાગી ગૃહસ્થ બાઈ ભાઈ સર્વ સત્સંગી તેમના સામાન્ય ધર્મ કહ્યા છે; કહેતાં સર્વ સત્સંગી માત્રને સરખા પાળવાના છે અને હવે એ સર્વેના જે વિશેષ ધર્મ છે તેમને પૃથ્વી પૃથ્વીપણે કરીને કહીએ છીએ.'),
(135, 'હવે ગૃહસ્થાશ્રમીના જે વિશેષ ધર્મ તે કહીએ છીએ. અમારે આશ્રિત જે ગૃહસ્થાશ્રમી પુરુષ તેમણે પોતાના સમીપ સંબંધ વિનાની જે વિધવા સ્ત્રીઓ તેમનો સ્પર્શ ન કરવો.'),
(136, 'અને તે ગૃહસ્થાશ્રમી પુરુષ તેમણે યુવાન અવસ્થાએ યુક્ત એવી જે પોતાની મા, બેન અને દીકરી તે સંગાથે પણ આપત્કાળ વિના એકાંતસ્થળને વિષે ન રહેવું અને પોતાની સ્ત્રીનું દાન કોઈને ન કરવું.'),
(137, 'અને જે સ્ત્રીને કોઈ પ્રકારના વ્યવહારે કરીને રાજાનો પ્રસંગ હોય તેવી સ્ત્રીનો જે પ્રસંગ તે કોઈ પ્રકારે પણ ન કરવો.'),
(138, 'અને તે ગૃહસ્થાશ્રમી તેમણે પોતાને ઘેર આવ્યો એવો જે અતિથિ તેને પોતાના સામર્થ્ય પ્રમાણે અન્નાદિકે કરીને પૂજવો અને વળી હોમાદિક જે દેવકર્મ અને શ્રાદ્ધાદિક જે પિતૃકર્મ તે જે તે પોતાના સામર્થ્ય પ્રમાણે યથાવિધિ જેમ ઘટે તેમ કરવું.'),
(139, 'અને અમારા આશ્રિત જે ગૃહસ્થ તેમણે માતા પિતા અને ગુરુ તથા રોગાતુર એવા જે કોઈ મનુષ્ય તેમની જે સેવા તે જીવનપર્યંત પોતાના સામર્થ્ય પ્રમાણે કરવી.'),
(140, 'અને વળી પોતાના વર્ણાશ્રમને ઘટિત એવો જે ઉદ્યમ તે પોતાના સામર્થ્ય પ્રમાણે કરવો અને કૃષિવૃત્તિવાળા જે ગૃહસ્થ સત્સંગી તેમણે બળદિયાના વૃષણનો ઉચ્છેદ ન કરવો.'),
(141, 'અને તે ગૃહસ્થ સત્સંગી તેમણે પોતાના સામર્થ્ય પ્રમાણે સમયને અનુસરીને જેટલો પોતાના ઘરમાં વરો હોય તેટલા અન્ન દ્રવ્યનો સંગ્રહ જે તે કરવો અને જેના ઘરમાં પશુ હોય એવા જે ગૃહસ્થ તેમણે પોતાના સામર્થ્ય પ્રમાણે ચાર્યપૂળાનો સંગ્રહ કરવો.'),
(142, 'અને ગાય, બળદ, ભેંસ, ઘોડા આદિક જે પશુ તેમની તૃણ જળાદિકે કરીને પોતાવતે જો સંભાવના થાય તો તે પશુને રાખવાં અને જો સંભાવના ન થાય તો ન રાખવાં.'),
(143, 'અને સાક્ષીએ સહિત લખત કર્યા વિના તો પોતાના પુત્ર અને મિત્રાદિક સાથે પણ પૃથ્વી ને ધનના લેણદેણે કરીને વ્યવહાર જેતે કયારેય ન કરવો.'),
(144, 'અને પોતાનું અથવા બીજાનું જે વિવાહ સંબંધી કાર્ય તેને વિષે આપવા યોગ્ય જે ધન તેનું સાક્ષીએ સહિત લખત કર્યા વિના કેવળ બોલી જ ન કરવી.'),
(145, 'અને પોતાની ઉપજનું જે દ્રવ્ય તેને અનુસારે નિરંતર ખરચ કરવો પણ તે ઉપરાંત ન કરવો અને જે ઉપજ કરતાં વધારે ખરચ કરે છે તેને મોટું દુઃખ થાય છે; એમ સર્વે ગૃહસ્થોએ મનમાં જાણવું.'),
(146, 'અને પોતાના વ્યવહાર કાર્યને વિષે જેટલા ધનની ઉપજ હોય તથા જેટલો ખરચ હોય તે બેયને સંભારીને નિત્યપ્રત્યે રૂડા અક્ષરે કરીને પોતે તેનું નામું લખવું.'),
(147, 'અને તે ગૃહસ્થાશ્રમી સત્સંગી તેમણે પોતાની જે વૃત્તિ અને ઉદ્યમ તે થકી પામ્યું જે ધન ધાન્યાદિક તે થકી દશમો ભાગ કાઢીને શ્રીકૃષ્ણભગવાનને અર્પણ કરવો અને જે વ્યવહારે દુર્બળ હોય તેમણે વીસમો ભાગ અર્પણ કરવો.'),
(148, 'અને એકાદશી આદિક જે વ્રત તેમનું જે ઉદ્યાપન તે જેતે પોતાના સામર્થ્ય પ્રમાણે યથાશાસ્ત્ર કરવું તે ઉદ્યાપન કેવું છે તો મનવાંછિત ફળનું આપનારું છે.'),
(149, 'અને શ્રાવણ માસને વિષે શ્રી મહાદેવનું પૂજન જેતે બિલ્વપત્રાદિકે કરીને પ્રીતિપૂર્વક સર્વ પ્રકારે પોતે કરવું અથવા બીજા પાસે કરાવવું.'),
(150, 'અને પોતાના જે આચાર્ય તે થકી તથા શ્રીકૃષ્ણ ભગવાનના જે મંદિર તે થકી કરજ ન કાઢવું અને વળી તે પોતાના આચાર્ય થકી અને શ્રીકૃષ્ણના મંદિર થકી પોતાના વ્યવહારને અર્થે પાત્ર, ઘરેણાં અને વસ્ત્રાદિક જે વસ્તુ તે માગી લાવવા નહીં.'),
(151, 'અને શ્રીકૃષ્ણ ભગવાન તથા પોતાના ગુરુ તથા સાધુ એમના દર્શન કરવાને અર્થે ગયે સતે માર્ગને વિષે પારકું અન્ન ખાવું નહિ તથા શ્રીકૃષ્ણ ભગવાન તથા પોતાના ગુરુ તથા સાધુ તેમનાં જે સ્થાનક તેમને વિષે પણ પારકું અન્ન ખાવું નહિ; કેમ જે તે પારકું અન્ન તો પોતાના પુણ્યને હરી લે એવું છે; માટે પોતાની ગાંઠનું ખરચ ખાવું.'),
(152, 'અને પોતાનું કામકાજ કરવા તેડયા જે મજૂર તેમને જેટલું ધન અથવા ધાન્ય દીધાનું કહ્યું હોય તે પ્રમાણે જ આપવું પણ તેમાંથી ઓછું ન આપવું અને પોતા પાસે કોઈ કરજ માગતો હોય અને તે કરજ દઈ ચૂકયા હોઈએ તે વાતને છાની ન રાખવી તથા પોતાનો વંશ તથા કન્યાદાન તે પણ છાનું ન રાખવી અને દુષ્ટ એવા જે જન તેમની સાથે વ્યવહાર ન કરવો.'),
(153, 'અને જે ઠેકાણે પોતે રહેતા હોઈએ તે ઠેકાણે કોઈક કઠણ ભૂંડો કાળ અથવા શત્રુ અથવા રાજા તેમના ઉપદ્રવે કરીને સર્વ પ્રકારે પોતાની લાજ જતી હોય કે ધનનો નાશ થતો હોય કે પોતાના પ્રાણનો નાશ થતો હોય.'),
(154, 'અને તે જો પોતાના મૂળ ગરાસનું તથા વતનનું ગામ હોય તો પણ તેનો વિવેકી એવા જે અમારા સત્સંગી ગૃહસ્થ તેમણે તત્કાળ ત્યાગ કરી દેવો અને જ્યાં ઉપદ્રવ ન હોય તેવો જે બીજો દેશ તે પ્રત્યે જઈને સુખેથી રહેવું.'),
(115, 'અને ધનાઢય એવા જે ગૃહસ્થ સત્સંગી તેમણે હિંસાએ રહિત એવા જે વિષ્ણુ સંબંધી યજ્ઞ તે કરવા તથા તીર્થને વિષે તથા દ્વાદશી આદિક પર્વને વિષે બ્રાહ્મણ તથા સાધુ તેમને જમાડવા.'),
(156, 'તે ધનાઢય એવા જે ગૃહસ્થ સત્સંગી તેમણે ભગવાનના મંદિરને વિષે મોટા ઉત્સવ કરાવવા તથા સુપાત્ર એવા જે બ્રાહ્મણ તેમને નાનાં પ્રકારનાં દાન દેવાં.'),
(157, 'અને અમારે આશ્રિત એવા જે સત્સંગી રાજા તેમણે ધર્મશાસ્ત્રને આશરીને પોતાના પુત્રની પેઠે પોતાની પ્રજાનું પાલન કરવું ને પૃથ્વીને વિષે ધર્મનું સ્થાપન કરવું.'),
(158, 'અને રાજા તેમણે રાજ્યનાં જે સાત અંગ તથા ચાર ઉપાય તથા છ ગુણ તે જેતે લક્ષણે કરીને યથાર્થપણે જાણવાં અને તીર્થ જે ચાર મોકલ્યાનાં સ્થાનક તથા વ્યવહારના જાણનારા જે સભાસદ તથા દંડવા યોગ્ય જે માણસ તથા દંડવા યોગ્ય નહિ એવા જે માણસ એ સર્વને લક્ષણે કરીને યથાર્થપણે જાણવા.');